import math

def get_divisors(n):
    divs = set()
    for i in range(1, int(math.sqrt(n)) + 1):
        if n % i == 0:
            divs.add(i)
            divs.add(n // i)
    return sorted(list(divs))

def check_condition(n, divisors):
    if len(divisors) < 5:
        return False

    # Divisors are 1-indexed based on size. d_k is the k-th smallest divisor.
    # d2 is index 1 (0-indexed)
    # d3 is index 2
    # d5 is index 4

    d2 = divisors[1]
    d3 = divisors[2]
    d5 = divisors[4]

    # Condition to verify: n = d2*d3 + d2*d5 + d3*d5
    rhs = d2 * d3 + d2 * d5 + d3 * d5

    return n == rhs

def search_candidates(limit=1000):
    solutions = []
    for n in range(1, limit + 1):
        divisors = get_divisors(n)
        d_n = len(divisors)

        if d_n == 10 or d_n == 14:
            if check_condition(n, divisors):
                solutions.append((n, d_n))

    return solutions

# Search up to 1000 as per previous notes' scope
solutions = search_candidates(limit=1000)
print(solutions)

